def validate_flag(user_input, correct_flag):
    """
    Validates a user-submitted flag against the correct flag.
    Returns True if they match, False otherwise.
    """
    if user_input == correct_flag:
        return True
    return False

def process_submission(submitted_flag, target_flag):
    # Simple flag checker for CTF platform
    is_correct = validate_flag(submitted_flag, target_flag)
    if is_correct:
        return {"status": "correct", "message": "Flag accepted!"}
    else:
        return {"status": "incorrect", "message": "Try again."}
